eb09da09-6f6c-4502-bf74-f7b9f1343539.q:
// Pull messages from Syslog-cron where the process name is "CRON" or "CROND", the severity level is info, and the SyslogMessage contains "CMD".
// It also parses out the user and commandline from the message.
let RawCommands = Syslog
| where Facility =~ "cron"
| where SeverityLevel =~ "info"
| where ProcessName =~ "CRON" or ProcessName =~ "CROND"
| where SyslogMessage contains "CMD "
| project TenantId, TimeGenerated, Computer, SeverityLevel, ProcessName, SyslogMessage
| extend TrimmedSyslogMsg = trim_end(@"\)", SyslogMessage)
| parse TrimmedSyslogMsg with * "(" user  ") CMD (" cmdline
| project TenantId, TimeGenerated, Computer, user, cmdline;
// Count how many times a particular commandline has been seen based on unique Computer, User, and cmdline sets
let CommandCount = RawCommands
| summarize StartTime = min(TimeGenerated), EndTime = max(TimeGenerated), CmdlineCount = count() by Computer, user, cmdline;
// Count how many computers have run a particular user and cmdline pair
let DistComputerCount = RawCommands
| summarize ComputerCount = dcount(Computer) by TenantId, user, cmdline;
// Join above counts based on user and commandline pair
let CommandSummary = CommandCount | join (DistComputerCount) on user, cmdline
| project StartTime, EndTime, TenantId, user, CmdlineCount, ComputerCount, cmdline;
// Count the total number of computers reporting cron messages in the tenant
let TotalComputers = Syslog
| where Facility =~ "cron"
| summarize dcount(Computer) by TenantId ;
// Join the previous counts with the total computers count. Calculate the percentage of total computers value.
let FinalSummary = CommandSummary | join kind= leftouter (TotalComputers) on TenantId
| project StartTime, EndTime, user, TimesCmdlineSeen = CmdlineCount, CompsThatHaveRunCmdline = ComputerCount,
AsPercentOfTotalComps = round(100 * (toreal(ComputerCount)/toreal(dcount_Computer)),2), cmdline
| order by user asc, TimesCmdlineSeen desc;
FinalSummary
| extend timestamp = StartTime, AccountCustomEntity = user

67af1633-311f-4a94-bc8f-f904a54637b2.q:
let aws_public_ips = externaldata(prefixes: string)
[
h@'https://aka.ms/awspublicipaddresse/aws-public-ip-addresses/ip-ranges.json'
]
with(format='multijson');
let timeframe = 30m;
let lookback = 12h;
//Get the AccessKey in the STS token (IMDS) when EC2 service assumes the Role periodically
let sts_token = AWSCloudTrail
| where TimeGenerated >= ago (lookback)
| where EventSource == "sts.amazonaws.com" and SourceIpAddress == "ec2.amazonaws.com"
| extend instanceId = tostring(parse_json(RequestParameters).roleSessionName)
| extend token = tostring(parse_json(ResponseElements).credentials.accessKeyId);
//Identify if the EC2 belongs to ECS/EKS
let typeOfEC2 = AWSCloudTrail
| where TimeGenerated >= ago (lookback)
| extend instanceId = tostring(split(UserIdentityPrincipalid, ":")[1])
| join sts_token on instanceId
| where UserAgent startswith "Amazon ECS Agent"
| project-away SourceIpAddress1, UserIdentityUserName1, UserIdentityArn1, TimeGenerated1;
//Get the identities who used that STS token - this can be the EC2 which assumed it (legit),
//but it can also be an external identity (attacker) which abuses the token permissions
let tokenUsage = AWSCloudTrail
| where TimeGenerated >= ago (timeframe)
| join kind=inner typeOfEC2 on $left.UserIdentityAccessKeyId == $right.token
| extend region = AWSRegion
| project-away SourceIpAddress1, UserIdentityUserName1, UserIdentityArn1, TimeGenerated1;
//Check whether the called identity is legit
aws_public_ips
| mv-expand todynamic(prefixes)
| extend ip_prefix=tostring(todynamic(prefixes.['ip_prefix']))
| extend region=tostring(todynamic(prefixes.['region']))
| extend service=tostring(todynamic(prefixes.['service']))
| project-away prefixes
| where service == "EC2"
| join kind=inner tokenUsage on region
| where SourceIpAddress !contains "amazonaws.com"
| where ipv4_is_private(SourceIpAddress) == false
| extend IsInRange = ipv4_is_in_range(SourceIpAddress, ip_prefix)
| extend UserIdentityUserName = iff(isnotempty(UserIdentityUserName), UserIdentityUserName, tostring(split(UserIdentityArn,'/')[-1]))
| summarize TimeGenerated=arg_max(TimeGenerated,*), r = make_set(IsInRange, 100) by SourceIpAddress, UserIdentityUserName, UserIdentityArn
| where not (set_has_element(r, true))
| project-away ip_prefix, IsInRange

e0d57543-acbd-428b-bb96-24a67506f84d.q:
let starttime = todatetime('{{StartTimeISO}}');
let endtime = todatetime('{{EndTimeISO}}');
let lookback = starttime - 14d;
// Generating historical table of all events per AccountId and Region
let EventInfo_CurrentDay =  materialize (AWSCloudTrail | where TimeGenerated between(starttime..endtime));
let EventInfo_historical = AWSCloudTrail  | where TimeGenerated  between (lookback..starttime) | summarize max(TimeGenerated) by AWSRegion, UserIdentityAccountId;
// Doing Leftanti join to find new regions historically not seen for the same account.
let EventInfo_Unseen = materialize (
EventInfo_CurrentDay
| summarize max(TimeGenerated) by AWSRegion, UserIdentityAccountId
| join kind= leftanti
(
EventInfo_historical
) on AWSRegion, UserIdentityAccountId
);
EventInfo_Unseen
// Join Ununsed region seen with current data to gather context about API events seen
| join kind= inner (
EventInfo_CurrentDay
) on AWSRegion, UserIdentityAccountId
| extend UnusedRegion = AWSRegion
| extend UserIdentityUserName = iff(isnotempty(UserIdentityUserName), UserIdentityUserName, tostring(split(UserIdentityArn,'/')[-1]))
| summarize EventCount = count(), StartTime = min(TimeGenerated), EndTime = max(TimeGenerated), EventNameList=make_set(EventName, 100), IPList=make_set(SourceIpAddress, 100) by UserIdentityAccountId, UnusedRegion, UserIdentityUserName
| order by StartTime desc

