564bf64a-bada-4c6b-8821-53138d660f78.q:
// DETECTION STRATEGY: Rootkit & BYOVD Ring-0 Network Bypass Detection via Firewall-to-EDR Telemetry Delta.
// THE MECHANIC: Advanced adversaries operating in Ring-0 via BYOVD can unlink WFP callouts, blinding MDE to outbound network telemetry while the host otherwise appears healthy.
// THE RESILIENCE: By comparing "Network Truth" (out-of-band firewall logs) against "Host Truth" (EDR telemetry), we trap the adversary. Endpoint tampering cannot hide the physical packet leaving the perimeter.

// Disclaimer: This query can be computationally expensive if run too frequently.

// NOTE ON ANALYTICS RULE CONVERSION, SCOPING & COMPUTE:
// If converting this Hunting Query into a scheduled Analytics Rule, you MUST do the following to preserve compute and prevent false positives:
// 1. Scope 'activeMdeNodes' strictly to "Crown Jewel" critical servers (e.g., Domain Controllers, PKI) to limit the left-anti join compute footprint.
// 2. Introduce an ingestion offset using "ago()" (e.g., | where TimeGenerated between (ago(24h) .. ago(1h))) to account for MDE telemetry batching delays and prevent "Ghost Deltas".

// Time framing: Hunting blade passes the selected time automatically via StartTimeISO and EndTimeISO
let starttime = todatetime('{{StartTimeISO}}');
let endtime = todatetime('{{EndTimeISO}}');

// Thresholds: Avoid micro-session noise, DHCP churn, or transient TCP handshakes.
let byteThreshold = 50000;
let connThreshold = 5;

// Tier 1: Firewall Perimeter Identification
// ADAPTATION: Analysts MUST adjust these arrays to match their specific perimeter security stack.
let firewallVendors = dynamic(["Palo Alto Networks", "Fortinet", "Check Point", "Cisco", "Zscaler"]);
let firewallProducts = dynamic(["Firewall", "PAN-OS", "FortiGate"]);

// STEP 1: Identify Active MDE Endpoints (Base Query)
// Why: We must ensure the source IP belongs to a machine actively running MDE.
// Note: Without this, unmanaged devices (IoT, BYOD) will trigger massive false positives.
let activeMdeNodes = DeviceNetworkEvents
| where Timestamp between (starttime .. endtime)
| where isnotempty(LocalIP)
| distinct LocalIP;

// STEP 2: Establish "Network Truth" via Perimeter Appliances
let firewallTruth = ASimNetworkSessionLogs
| where TimeGenerated between (starttime .. endtime)
| where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
| where NetworkProtocol in~ ("TCP")
// CONDITION A: Verify the log comes from a perimeter hardware/virtual appliance
| where EventVendor has_any (firewallVendors) or EventProduct has_any (firewallProducts)
// CONDITION B: Filter out internal-to-internal traffic to focus exclusively on external C2/Exfiltration
| where ipv4_is_private(DstIpAddr) == false
and ipv4_is_private(SrcIpAddr) == true
// CONDITION C: Ensure the source IP is an active MDE node (Filter early for compute efficiency)
| where SrcIpAddr in (activeMdeNodes)
// Preserving Context: Use make_set to keep analyst context without blowing up row counts
| summarize firewallConnCount = count(),
totalBytes = sum(tolong(NetworkBytes)),
StartTime = min(TimeGenerated),
EndTime = max(TimeGenerated),
destinationPorts = make_set(DstPortNumber, 100),
appProtocols = make_set(NetworkApplicationProtocol, 100)
by SrcIpAddr, DstIpAddr
| where totalBytes >= byteThreshold or firewallConnCount >= connThreshold;

// STEP 3: Establish "Host Truth" via EDR Telemetry
let mdeTruth = DeviceNetworkEvents
| where Timestamp between (starttime .. endtime)
| where isnotempty(LocalIP) and isnotempty(RemoteIP)
| where Protocol in~ ("TCP")
| where ipv4_is_private(RemoteIP) == false
// Join Optimization: Use distinct to drastically reduce memory footprint before the anti-join
| distinct LocalIP, RemoteIP
| project SrcIpAddr = LocalIP, DstIpAddr = RemoteIP;

// STEP 4: Capture Endpoint Context & Strict Schema Parsing
let deviceMapping = DeviceNetworkInfo
| where Timestamp between (starttime .. endtime)
| where isnotempty(IPAddresses) and isnotempty(DeviceName)
// Expand the JSON array of IP addresses so each IP gets its own row
| extend parsedIPs = todynamic(IPAddresses)
| mv-expand parsedIPs
| extend LocalIP = tostring(parsedIPs.IPAddress)
| where isnotempty(LocalIP)
// Get the most recent heartbeat for each IP address to account for DHCP churn
| summarize arg_max(Timestamp, DeviceName, DeviceId) by LocalIP
| project SrcIpAddr = LocalIP, RawDeviceName = DeviceName, DeviceId = tostring(DeviceId);

// STEP 5: Execute the Delta Anti-Join
firewallTruth
// Left Anti-Join: Keep ONLY the connections seen by the Firewall that are completely missing from MDE
| join hint.strategy=shuffle kind=leftanti (
mdeTruth
) on SrcIpAddr, DstIpAddr
// Enrich with Device Details
| join kind=leftouter (
deviceMapping
) on SrcIpAddr

// EXCLUSION: Built-in tuning guidance for org-specific baselines.
// | where DstIpAddr !in~ ("8.8.8.8", "1.1.1.1") // Example: Exclude common DNS bypasses

// Data Sanitization
// Rename generic schema columns into distinct, narrative evidence
| extend timestamp = StartTime,
InternalIP = tostring(SrcIpAddr),
DestinationIP = tostring(DstIpAddr),
EvasiveConnectionCount = firewallConnCount,
TotalBytesSent = totalBytes,
DestinationPorts = destinationPorts,
HostName = tostring(split(RawDeviceName, ".")[0]),
DnsDomain = iff(RawDeviceName contains ".", substring(RawDeviceName, indexof(RawDeviceName, ".") + 1), "")


// ANALYST ACTION: Check 'DestinationIP' against Threat Intel.
// If the IP is a known SaaS/Cloud provider, verify if frequency matches beaconing patterns or if the 'TotalBytesSent' aligns with
// anomalous Rclone/exfiltration activity. Run a live response memory scan for hidden drivers.

// Ordering Visual Hierarchy
// Drop raw artifacts and display the chronology left-to-right
| project timestamp,
StartTime,
EndTime,
HostName,
DnsDomain,
DeviceId,
InternalIP,
DestinationIP,
EvasiveConnectionCount,
TotalBytesSent,
DestinationPorts,
appProtocols
| project-reorder timestamp,
HostName,
InternalIP,
DestinationIP,
EvasiveConnectionCount,
TotalBytesSent,
DestinationPorts,
appProtocols
| order by TotalBytesSent desc

2df3fa1f-d573-4e0a-82f2-da62d3f2973f.raw:
id: 2df3fa1f-d573-4e0a-82f2-da62d3f2973f
name: Anomalous .NET runtime loading for fileless payload
description: |
  Identifies native processes or binaries in writable paths loading .NET runtimes. This suggests in-memory code injection and ETW patching used by malware to execute code while evading detection by security tools.

description-detailed: |
  Identifies native Windows binaries or processes in user-writable folders that unexpectedly load the .NET runtime engine. This activity is anomalous because these processes are not built on .NET and typically do not require these files to function. Malware uses this technique to execute malicious code entirely in memory, often while attempting to disable security logging (ETW patching) to remain invisible. Legitimate .NET applications usually run from secure directories like Program Files and are digitally signed by known vendors.
  References:
  https://www.microsoft.com/en-us/security/blog/2026/05/14/kazuar-anatomy-of-a-nation-state-botnet/
  https://r136a1.dev/2026/01/14/command-and-evade-turlas-kazuar-v3-loader/

requiredDataConnectors:
  - connectorId: MicrosoftThreatProtection
    dataTypes:
      - DeviceImageLoadEvents
tactics:
  - DefenseEvasion
  - Execution
relevantTechniques:
  - T1562.001
  - T1055
query: |
  // -----------------------------------------------------------------------------
  // DETECTION STRATEGY: ETW-Patching Resistant .NET In-Memory Execution
  // 
  // THE MECHANIC: Advanced malware (like Kazuar) often executes .NET payloads 
  // entirely in memory to avoid disk-based antivirus scans. To hide this execution 
  // from EDRs, the malware patches Event Tracing for Windows (ETW) in user-mode 
  // (e.g., overwriting ntdll.dll!EtwEventWrite with a return instruction). This blinds 
  // the EDR, preventing it from seeing the standard 'ClrUnbackedModuleLoaded' 
  // events that usually trigger memory execution alerts.
  //
  // THE RESILIENCE: While user-mode ETW can be easily patched by malware running 
  // with standard privileges, the malware CANNOT hide the physical loading of the 
  // .NET runtime engine (CLR) DLLs themselves. DLL loads trigger kernel-level 
  // callbacks (PsSetLoadImageNotifyRoutine) which user-mode malware cannot intercept. 
  // This query relies exclusively on DeviceImageLoadEvents (kernel-driven telemetry) 
  // to detect when native Windows tools (LOLBins) or untrusted binaries running from 
  // user-writable paths unexpectedly load the .NET execution engine. By shifting 
  // detection to the kernel-level prerequisite of the attack, we render the user-mode 
  // ETW patch irrelevant.
  // -----------------------------------------------------------------------------

  // Define a list of native Windows binaries (LOLBins) that are written in C/C++.
  // Under normal circumstances, these native tools have no legitimate reason to boot 
  // up the .NET runtime. If they load 'clr.dll' or 'mscoree.dll', it is a highly reliable 
  // indicator that they have been hijacked (e.g., via malicious COM object instantiation) 
  // to host a fileless .NET payload.

  // Note: Binaries like powershell.exe, csc.exe, or msbuild.exe are built on or deeply integrated with
  // .NET, so loading clr.dll is perfectly normal for them.
  let AnomalousLOLBins = dynamic([
    // Tier 1: Most Heavily Abused Processes
    "rundll32.exe", "regsvr32.exe", "mshta.exe", "dllhost.exe", "svchost.exe", "spoolsv.exe", "werfault.exe", "explorer.exe",
    // Tier 2: Scripting & Automation Hosts
    "wscript.exe", "cscript.exe", "wmic.exe", "msiexec.exe",
    // Tier 3: Admin & Setup Utilities
    "odbcconf.exe", "control.exe", "cmstp.exe", "certutil.exe"
  ]);

  // Base Query: Look for the .NET Execution Engine DLLs being loaded into memory
  DeviceImageLoadEvents
  // STEP 1: Identify processes loading the .NET Common Language Runtime (CLR) engines.
  // 'mscoree.dll'   -> The traditional .NET execution engine.
  // 'clr.dll'       -> The core .NET framework runtime.
  // 'mscorwks.dll'  -> Legacy .NET workstation runtime.
  // 'coreclr.dll'   -> The modern .NET Core runtime.
  | where FileName in~ ("clr.dll", "mscoree.dll", "mscorwks.dll", "coreclr.dll")


  // STEP 2: Apply Behavioral Filters to isolate malicious injection/loading.
  // We use a strict Whitelist approach for paths. We only trust strict, Admin-secured directories.
  // By using regex anchored to the start of the string (^), we prevent attackers from 
  // bypassing the rule by creating a fake "Program Files" folder inside a user-writable 
  // directory (e.g., C:\Users\Public\Program Files\malware.exe).

  | extend IsTrustedPath = InitiatingProcessFolderPath matches regex @"^[a-zA-Z]:\\(?:Program Files|Program Files \(x86\)|Windows)(?:\\|$)"


  // STEP 2: Apply Behavioral Filters to isolate malicious injection/loading.
  | where 
    // CONDITION A: A native Windows LOLBin is suddenly loading the .NET engine.
    (InitiatingProcessFileName in~ (AnomalousLOLBins))
    or 
    // CONDITION B: An executable running from ANY untrusted, user-writable directory 
    // (AppData, Temp, PerfLogs, etc.) is loading the .NET engine.
    (not(IsTrustedPath))

  // EXCLUSION: Filter out poorly behaved legitimate software (like user-context auto-updaters) 
  // by ensuring the binary's internal version metadata does not belong to a trusted software vendor.
  // Note: Schema recommends using SHA1 over SHA256 as it is more reliably populated.
  // Insert legitimate internal tool hashes or signer here if they legitimately run .NET from Temp/AppData.
  // | where InitiatingProcessSHA1 !in~ ("<Legit_SHA1_1>", "<Legit_SHA1_2>")
  // | where InitiatingProcessVersionInfoCompanyName !in~ ( "Microsoft Corporation", "Google LLC", "Google Inc", "Cisco Systems, Inc.", "Intel Corporation" )

  // STEP 3: Format the output for triage.
  // We surface the Command Line, Folder Path, and SHA1 hash for immediate context.
  | extend ProcessIdString = tostring(InitiatingProcessId)
  | project 
    Timestamp,
    DeviceName, 
    ActionType,
    LoadedDll = FileName, 
    InitiatingProcessAccountDomain,
    InitiatingProcessAccountName,
    InitiatingProcessFileName, 
    InitiatingProcessFolderPath, 
    InitiatingProcessCommandLine, 
    ProcessIdString,
    InitiatingProcessParentFileName,
    InitiatingProcessVersionInfoCompanyName,
    InitiatingProcessSHA1
  | project-reorder 
    Timestamp,
    DeviceName,
    InitiatingProcessAccountDomain,
    InitiatingProcessAccountName,
    InitiatingProcessFileName,
    InitiatingProcessCommandLine,
    LoadedDll,
    InitiatingProcessFolderPath,
    InitiatingProcessParentFileName

entityMappings:
  - entityType: Host
    fieldMappings:
      - identifier: FullName
        columnName: DeviceName
  - entityType: Account
    fieldMappings:
      - identifier: Name
        columnName: InitiatingProcessAccountName
      - identifier: NTDomain
        columnName: InitiatingProcessAccountDomain
  - entityType: Process
    fieldMappings:
      - identifier: CommandLine
        columnName: InitiatingProcessCommandLine
      - identifier: ProcessId
        columnName: ProcessIdString
version: 1.0.0

